-- Тема 9: Расположение ТС на проезжей части — топик id=9, категория id=8
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(8,9,'На какой полосе должны двигаться тихоходные транспортные средства на дороге с несколькими полосами?',
'["По крайней правой полосе","По любой полосе на выбор водителя","По крайней левой полосе","По разделительной полосе"]'::jsonb,0,
'Тихоходные ТС, а также ТС, скорость которых по техническим причинам ниже установленной, должны двигаться по крайней правой полосе, кроме случаев объезда или обгона.',1),
(8,9,'Разрешено ли движение по обочине?',
'["Запрещено, кроме случаев остановки, стоянки, вынужденной остановки или движения велосипедистов, гужевых повозок","Разрешено без ограничений","Разрешено только грузовым ТС","Разрешено, если полосы движения загружены"]'::jsonb,0,
'Движение по обочине запрещено, кроме случаев остановки, стоянки в установленных местах, вынужденной остановки, а также в отдельных случаях для велосипедов, мопедов и гужевых повозок.',2),
(8,9,'На дороге с двусторонним движением, имеющей четыре полосы без разметки, где должны двигаться ТС?',
'["Не далее второй полосы от правого края","Строго по одной крайней правой полосе","Только по левой стороне","В любой полосе без ограничений"]'::jsonb,0,
'На дорогах с двусторонним движением, имеющих четыре и более полос без разметки, запрещается выезжать для движения или объезда далее второй полосы от правого края.',3),
(8,9,'Что означает термин "средняя полоса" на дороге с тремя полосами без разметки при двустороннем движении?',
'["Предназначена для движения в обоих направлениях (обгон, объезд, поворот налево) с обязательным освобождением при завершении манёвра","Предназначена только для одного направления","Полностью запрещена для движения","Является разделительной полосой"]'::jsonb,0,
'При трёх полосах без разметки на дороге с двусторонним движением средняя полоса предназначена для движения в обоих направлениях: её можно использовать для обгона, объезда или поворота налево.',4),
(8,9,'Где должны двигаться маршрутные ТС, если для них выделена специальная полоса, обозначенная разметкой и знаком?',
'["По выделенной полосе, движение по ней других ТС запрещено, если не оговорено иное","По любой полосе на усмотрение водителя","Выделенная полоса используется только в час пик","Полоса предназначена для парковки"]'::jsonb,0,
'Полоса для маршрутных ТС, обозначенная знаком 5.14 и разметкой 1.23, предназначена для движения маршрутных ТС; движение и остановка на ней иных ТС запрещены, кроме специально оговорённых случаев.',5);

-- Тема 10: Скорость движения — топик id=10, категория id=9
INSERT INTO t_p22961065_vector_driving_instr.pdd_questions (category_id, topic_id, text, options, correct_index, explanation, sort_order) VALUES
(9,10,'Какая максимальная скорость разрешена в жилых зонах и на дворовых территориях?',
'["20 км/ч","40 км/ч","60 км/ч","10 км/ч"]'::jsonb,0,
'В жилых зонах и на дворовых территориях разрешена скорость не более 20 км/ч, также запрещено сквозное движение и учебная езда.',1),
(9,10,'Какая максимальная скорость разрешена легковым автомобилям в населённых пунктах?',
'["60 км/ч","80 км/ч","90 км/ч","50 км/ч"]'::jsonb,0,
'В населённых пунктах разрешается движение со скоростью не более 60 км/ч, если знаками не установлено иное ограничение.',2),
(9,10,'Какая максимальная скорость разрешена легковым автомобилям на автомагистралях?',
'["110 км/ч","90 км/ч","130 км/ч","100 км/ч"]'::jsonb,0,
'Вне населённых пунктов на автомагистралях легковым автомобилям разрешена скорость не более 110 км/ч.',3),
(9,10,'Обязан ли водитель учебного ТС с обучаемым соблюдать особые ограничения скорости?',
'["Да, скорость учебной езды не должна превышать 40 км/ч на дорогах в населённых пунктах, если иное не установлено","Ограничений нет","Максимум 20 км/ч в любых условиях","Ограничение действует только вне города"]'::jsonb,0,
'При учебной езде на дорогах в населённых пунктах устанавливаются дополнительные требования безопасности, скорость должна соответствовать уровню подготовки обучаемого и не создавать опасности.',4),
(9,10,'Какую скорость обязан выбирать водитель при возникновении опасности для движения?',
'["Снизить скорость вплоть до полной остановки транспортного средства","Продолжать движение с той же скоростью","Увеличить скорость, чтобы избежать опасности","Скорость не имеет значения при опасности"]'::jsonb,0,
'При возникновении опасности для движения, которую водитель в состоянии обнаружить, он должен принять меры к снижению скорости вплоть до остановки ТС.',5),
(9,10,'Какая скорость разрешена при буксировке механического ТС на гибкой сцепке?',
'["Не более 50 км/ч","Не более 20 км/ч","Не более 90 км/ч","Ограничений нет"]'::jsonb,0,
'При буксировке на гибкой сцепке скорость не должна превышать 50 км/ч, а на жёсткой сцепке — тоже действуют дополнительные ограничения по безопасности.',6);
